                    asSet(cand, row, AC_BX0, bx0);
                    asSet(cand, row, AC_BX0 + 1, by0);
                    asSet(cand, row, AC_BX0 + 2, bx1);
                    asSet(cand, row, AC_BX0 + 3, by1);
                    asSet(cand, row, AC_VX0, vx0);
                    asSet(cand, row, AC_VX0 + 1, vy0);
                    asSet(cand, row, AC_VX0 + 2, vx1);
                    asSet(cand, row, AC_VX0 + 3, vy1);
                    asSet(cand, row, AC_OBJ, obj);
                    asSet(cand, row, AC_FROM, Model.afmRaw());
                    asSet(cand, row, AC_ORIGIN, Model.aoDecoded());
                    asSet(cand, row, AC_TYPE, Model.amtPng());
                    asSet(cand, row, AC_KORI, -1);
                    asSet(cand, row, AC_FLAGS, flags);
